ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	shippedItemInstance: vars.ceresShipmentCSV filter ($.ShipmentNumber as String == vars.shipmentId as String) map ( payload01 , indexOfPayload01 ) -> {
		typeCode: 'seed',
		identifier: {
			content: payload01.ShipmentNumber ++ "-" ++ payload01.SeqCode,
			typeCode: "shipment_line_identifier"
		},
		item: {
			brandName: payload01.SeedBrand,
			manufacturerItemIdentification: {
				identifier: if ( payload01.Crop == "TREATMENT" ) (payload01.ItemNumber) else '',
				typeCode: if ( payload01.Crop == "TREATMENT" ) ("SKU") else ''
			},
			description: payload01.Description,
			gtinid: if ( payload01.Crop != "TREATMENT" and sizeOf(payload01.Crop) > 12 ) (payload01.ItemNumber) else '',
			varietyName: payload01.ShortDescription,
			productName: payload01.ShortDescription
		},
		quantity: {
			unitCode: payload01.UOM,
			content: payload01.Quantity as Number
		},
		description: {
			content: payload01.DisplayDescription,
			typeCode: "mics_display"
		},
		classification: {
			codes: {
				code: [{
					content: if ( payload01.Crop == "Corn" or payload01.Crop == "CORN" ) ("C") else 
						if ( payload01.Crop == "Soybeans" or payload01.Crop == "SOYBEANS" ) ("S") else 
						if ( payload01.Crop == "Alfalfa" or payload01.Crop == "ALFALFA" ) ("ALF") else 
						if ( payload01.Crop == "Cotton" or payload01.Crop == "COTTON" ) ("CTN") else 
						if ( payload01.Crop == "Wheat" or payload01.Crop == "WHEAT" ) ("SW") else 
						if ( payload01.Crop == "SpringWheat" or payload01.Crop == "SPRINGWHEAT" ) ("SW") else 
						if ( payload01.Crop == "WinterWheat" or payload01.Crop == "WINTERWHEAT" ) ("WW") else 
						"",
					listAgencyIdentifier: "AGIIS",
					typeCode: payload01.Crop
				},
								{
					content: payload01.SeedTrait,
					typeCode: 'Trait'
				}]
			},
			typeCode: "Crop"
		},
		lot: {
			identifier: {
				content: payload01.LotId,
				typeCode: 'Lot'
			}
		},
		documentReference: {
			identifier: {
				content: payload01.ShipmentNumber
			},
			typeCode: 'shipment_identifier',
			documentDateTime: if ( payload01.OrderDate contains "-" ) (payload01.OrderDate ++"T00:00:00.000-05:00") else 
			if ( sizeOf(payload01.OrderDate) == 8 ) (payload01.OrderDate[0 to 3] ++ "-" ++ payload01.OrderDate[4 to 5] ++ "-" ++  payload01.OrderDate[6 to 7] ++
				"T00:00:00.000-05:00") 
				else ""
		},
		manufacturingParty: {
			name: payload01.ManufacturerName
		},
		party: [{
			identifier: [{
				content: payload01.CustomerNumber,
				typeCode: "retailer_grower_identifier"
			}],
			name: payload01.CustomerLookupName,
			location: {
				glnid: payload01.CustomerGLN
			},
			typeCode: 'Grower'
		},
		{
			name: payload01.Retailer,
			location: {
				glnid: payload01.RetailerGLN
			},
			typeCode: 'Retailer'
		}],
		itemIdentifierSet: [{
			identifier: [{
				content: payload01.SeedTreatments,
				typeCode: "product"
			}],
			schemeAgencyIdentifier: "manufacturer_seed_treatment_identifier",
			schemeIdentifier: payload01.SeedTreatments,
			typeCode: "seed_treatment"
		}]
	}
}
